import type { Agent } from "../types";

/**
 * Per-pack character skins. The Tarkov pack dresses the pr-patrol crew as operators
 * (public/sprites/101..105, generated by scripts/sprites/generate-tarkov-sprites.py); any other
 * agent gets one of the five by id. Other packs keep each agent's own sprite.
 */
const TARKOV_SPRITES: Record<string, number> = {
  Argus: 101, // recon / marksman: reviews
  Patch: 102, // engineer: review fixes
  Medic: 103, // medic: CI fixes
  Weaver: 104, // sapper: merge conflicts
  Gate: 105, // checkpoint sentry: readiness
};

/** Sprite numbers the office must preload so switching packs never shows a missing texture. */
export const PACK_SKIN_SPRITE_NUMS = [101, 102, 103, 104, 105];

let activeSkin: Record<string, number> | null = null;

export function setPackSpriteSkin(packKey: string): void {
  activeSkin = packKey === "tarkov" ? TARKOV_SPRITES : null;
}

export function packSkinSpriteFor(agent: Agent): number | undefined {
  if (!activeSkin) return undefined;
  const named = activeSkin[agent.name];
  if (named) return named;
  let hash = 0;
  for (let i = 0; i < agent.id.length; i += 1) hash = (hash * 31 + agent.id.charCodeAt(i)) >>> 0;
  return PACK_SKIN_SPRITE_NUMS[hash % PACK_SKIN_SPRITE_NUMS.length];
}
